                                reachedPitch = true;
                                break;
                            }

                            prefix.Add(s);
                        }

                        if (prefix.Count == 0)
                            continue;
                        if (end != 0)
                            prefix.Reverse();
                        var left = new List<CurveArea511.P>();
                        var right = new List<CurveArea511.P>();
                        var first = prefix[0];
                        left.Add(Convert(first.l0, first.lo, transpose));
                        right.Add(Convert(first.r0, first.lo, transpose));
                        for (int n = 0; n < prefix.Count; n++)
                        {
                            var s = prefix[n];
                            bool last = n + 1 == prefix.Count;
                            if (last || prefix[n + 1].left != s.left)
                                left.Add(Convert(s.l1, s.hi, transpose));
                            if (last || prefix[n + 1].right != s.right)
                                right.Add(Convert(s.r1, s.hi, transpose));
                        }

                        var polygon = new List<CurveArea511.P>(left);
                        right.Reverse();
                        polygon.AddRange(right);
                        for (int n = polygon.Count - 1; n > 0; n--)
                            if (polygon[n].x == polygon[n - 1].x && polygon[n].y == polygon[n - 1].y)
                                polygon.RemoveAt(n);
                        if (polygon.Count > 1 && polygon[0].x == polygon[polygon.Count - 1].x && polygon[0].y == polygon[polygon.Count - 1].y)
                            polygon.RemoveAt(polygon.Count - 1);
                        double signed = 0;
                        for (int n = 0; n < polygon.Count; n++)
                        {
                            var a = polygon[n];
                            var b = polygon[(n + 1) % polygon.Count];
                            signed += a.x * b.y - a.y * b.x;
                        }

                        if (polygon.Count < 3 || signed == 0)
                            continue;
                        if (signed < 0)
                            polygon.Reverse();
                        double lo = branch.geometry[0].lo, hi = branch.geometry[branch.geometry.Count - 1].hi, fl = prefix[0].lo, fh = prefix[prefix.Count - 1].hi;
                        output.decisions.Add(new Decision{sourceBranch = branch.boundaryId, axis = transpose ? "x" : "y", mode = reachedPitch ? "FILL_CAP_KEEP_REMAINDER" : "FILL_SOURCE_BRANCH", splitRule = "first continuous cap width reaches one grid pitch; no cell-count or centre threshold", pitch = pitch, sourceLo = lo, sourceHi = hi, fillLo = fl, fillHi = fh, keepLo = end == 0 ? fh : lo, keepHi = end == 0 ? hi : fl, insertedRing = output.rings.Count, positiveLeftBoundary = branch.leftPath566.ToArray(), positiveRightBoundary = branch.rightPath566.ToArray(), sourceStart = Copy(branch.start566), sourceEnd = Copy(branch.end566), selectedPortStatus = "NOT_RESOLVED"});
                        output.rings.Add(polygon.ToArray());
                        filledAll = !reachedPitch;
                    }
                }
            }

            return output;
        }
    }

    [Serializable]
    public sealed class Port
    {
        public string kind;
        public double level, left, right;
        public long leftId, rightId;
    }

    [Serializable]
    public sealed class Decision
    {
        public string sourceBranch, axis, mode, splitRule;
        public double pitch, sourceLo, sourceHi, fillLo, fillHi, keepLo, keepHi;
        public int insertedRing;
        public long[] positiveLeftBoundary, positiveRightBoundary;
        public Port sourceStart, sourceEnd;
        public int[] selectedPortCells;
        public string selectedPortStatus;
    }

    public sealed class Build
    {
        public readonly List<CurveArea511.P[]> rings = new();
        public readonly List<Decision> decisions = new();
        public readonly List<NegativeRegion563.Feature> sourceBranches = new();
        public readonly List<bool> transposed = new();
    }
}
